<?php
require __DIR__.'/../../config/database.php';require __DIR__.'/../../config/helpers.php';if(!isset($_SESSION['ID_USER'])){header('Location: /index.php');exit;}requireRole(0);$id=(int)($_GET['id_ocorrencia']??0);$s=$con->prepare('SELECT titulo,data_ocorr,descricao,ID_MAQ,ID_LAB,tipo_problema,status_ocorrencia FROM Ocorrencias WHERE ID_OCORR=?');$s->bind_param('i',$id);$s->execute();$s->bind_result($titulo,$data,$descricao,$maq,$lab,$tipo,$status);$found=$s->fetch();$s->close();if(!$found){header('Location: /suporte/laboratorio.php');exit;}$info=statusInfo((int)$status);$pdf=new SimplePdf();$m=$pdf->marginX();$pdf->setColor(17,17,17);$pdf->setFont('B',18);$pdf->text($titulo);$pdf->setXY($m,$pdf->getY()-28);$pdf->setColor(90,90,90);$pdf->setFont('R',10);$pdf->text('Gerado em '.date('d/m/Y H:i'));$pdf->setXY($m,$pdf->getY()-30);foreach(['Laboratório'=>(string)$lab,'Máquina'=>$maq?'#'.$maq:'Não especificada','Tipo'=>(string)$tipo,'Data'=>(string)$data,'Status'=>$info['label']] as $label=>$value){$pdf->setColor(90,90,90);$pdf->setFont('B',9);$pdf->text(strtoupper($label));$pdf->setColor(17,17,17);$pdf->setFont('R',12);$pdf->text($value,$m+150);$pdf->setXY($m,$pdf->getY()-20);}$pdf->setXY($m,$pdf->getY()-10);$pdf->setColor(90,90,90);$pdf->setFont('B',9);$pdf->text('DESCRIÇÃO');$pdf->setXY($m,$pdf->getY()-18);$pdf->setColor(17,17,17);$pdf->setFont('R',11);foreach($pdf->wrapText((string)$descricao,$pdf->contentWidth()) as $line){$pdf->ensureSpace(16);$pdf->text($line);$pdf->setXY($m,$pdf->getY()-16);}$pdf->download('ocorrencia-'.$id.'.pdf');
